from pathlib import Path
s='''// Generated by deps/generate_symmetric.py.
// Casts intentionally keep the f32/f64 and LP64/ILP64 formulae identical.
#![allow(clippy::unnecessary_cast)]
use crate::lapack::*;
use crate::kernels::flag;
'''
for p,t,r,c in [('s','f32','f32',False),('d','f64','f64',False),('c','colmat::c32','f32',True),('z','colmat::c64','f64',True)]:
 for I,suffix in [('i32','_'),('i64','_64_')]:
  family='heev' if c else 'syev'
  for ending in ['','d','r']:
   name=p+family+ending+suffix
   common=f'j:*const u8,'+(f'range:*const u8,' if ending=='r' else '')+f'u:*const u8,n:*const {I},a:*mut {t},lda:*const {I},'
   if ending=='r':common+=f'vl:*const {r},vu:*const {r},il:*const {I},iu:*const {I},_abstol:*const {r},m:*mut {I},w:*mut {r},z:*mut {t},ldz:*const {I},support:*mut {I},'
   else:common+=f'w:*mut {r},'
   common+=f'work:*mut {t},lwork:*const {I},'
   if c:common+=f'{"rwork" if ending else "_rwork"}:*mut {r},'+(f'lrwork:*const {I},' if ending else '')
   if ending:common+=f'iwork:*mut {I},liwork:*const {I},'
   common+=f'info:*mut {I}'
   s+=f'#[no_mangle]\npub unsafe extern "C" fn {name}({common}){{\n *info=0;let(job,u,nn,la,lw)=(flag(j),flag(u),(*n).val(),(*lda).val(),(*lwork).val());\n'
   uarg,narg,ldarg=(3,4,6) if ending=='r' else (2,3,5)
   checks=[(1,"matches!(job,b'N'|b'V')"),(uarg,"crate::kernels::uplo(u)"),(narg,'nn>=0'),(ldarg,'la>=1.max(nn)')]
   if ending=='r':
    s+=" let range=flag(range);\n"
    checks.insert(1,(2,"matches!(range,b'A'|b'V'|b'I')"))
    checks += [(8,"range!=b'V'||nn==0||*vl<*vu"),(9,"range!=b'I'||(*il>=1&&*il<=1.max(*n))"),(10,"range!=b'I'||(*iu>=0&&*iu<=*n&&(*iu>=*il||nn==0))"),(15,"*ldz>=1&&(job!=b'V'||*ldz>=*n)")]
    s+=' let need=1.max('+('2*nn' if c else '26*nn')+');let ine=1.max(10*nn);\n'
    if c:s+=' let rne=1.max(24*nn);\n'
    query='lw== -1||*liwork== -1'+('||*lrwork== -1' if c else '')
    lwarg=18;liwarg=22 if c else 20;rwarg=20
   elif ending=='d':
    if c:s+=" let need=if nn<=1{1}else if job==b'V'{2*nn+nn*nn}else{nn+1};let rne=if nn<=1{1}else if job==b'V'{1+5*nn+2*nn*nn}else{nn};\n"
    else:s+=" let need=if nn<=1{1}else if job==b'V'{1+6*nn+2*nn*nn}else{2*nn+1};\n"
    s+=" let ine=if nn<=1||job==b'N'{1}else{3+5*nn};\n"
    query='lw== -1||*liwork== -1'+('||*lrwork== -1' if c else '')
    lwarg=8;liwarg=12 if c else 10;rwarg=10
   else:
    s+=' let need=1.max('+('2*nn-1' if c else '3*nn-1')+');\n'
    query='lw== -1';lwarg=8
   s+=f' let query={query};\n'
   checks+=[(lwarg,'query||lw>=need')]
   if ending:checks+=[(liwarg,'query||(*liwork).val()>=ine')]
   if c and ending:checks+=[(rwarg,'query||(*lrwork).val()>=rne')]
   for arg,cond in checks:s+=f' if !({cond}){{bad(&mut *info,{arg});return;}}\n'
   s+=f' *work=workspace::<{t}>(need);'
   if ending:s+=f'*iwork=ine as {I};'
   if c and ending:s+=f'*rwork=workspace::<{r}>(rne);'
   s+='if query{return;}\n'
   if not ending=='r':s+=f' let mut count=0 as {I};\n'
   m='m' if ending=='r' else '&mut count'
   range_arg='range' if ending=='r' else "b'A'"
   vl_arg='*vl as f64,*vu as f64,(*il).val()as usize,(*iu).val()as usize' if ending=='r' else '0.0,0.0,1,nn as usize'
   zargs='z,(*ldz).val(),support' if ending=='r' else 'a,la,core::ptr::null_mut()'
   s+=f' if symmetric_driver(job,{range_arg},u,nn as usize,a,la,{vl_arg},{m},w,{zargs}).is_err(){{*info=1;}}\n}}\n'
Path('deps/rust/src/lapack_symmetric.rs').write_text(s)
